        foreach ($skillKeywordMap as $skill => $keywords) {
            $skillId = DB::table('user_skill')->where('skill', $skill)->value('id');

            if (!$skillId) {
                $this->command->warn("Skill \"$skill\" not found. Please run SkillSeeder first.");
                continue;
            }

            foreach ($keywords as $word) {
                $keywordId = DB::table('keyword')->where('keyword', $word)->value('id');

                if (!$keywordId) {
                    $this->command->warn("Keyword \"$word\" not found. Please run KeywordSeeder first.");
                    continue;
                }

                DB::table('keyword_mapping')->updateOrInsert(
                    ['skill_id' => $skillId, 'keyword_id' => $keywordId],
                    ['skill_id' => $skillId, 'keyword_id' => $keywordId]
                );
            }

            $this->command->info("Keywords mapped to skill \"$skill\".");
        }
